def get_file_contents(owner, repo, path=None, ref=None, sha=None, **_extra):
    import json, os, datetime, base64, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0110000" if __import__("os").path.isdir("./environment_mix/0110000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "success"
    err = None

    def _ensure_store_shape(db):
        if isinstance(db, dict):
            return db
        return {"me": None, "users": [], "repos": [], "branches": [], "files": [], "issues": [], "issue_comments": [],
                "pulls": [], "pr_files": [], "commits": [], "tags": [], "releases": [], "labels": [], "teams": [],
                "issue_types": [], "reviews": [], "audit_log": [], "usage": {"requests": 0}}

    def _audit(db, endpoint, status, error_code=None):
        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        lat_ms = int((time.time() - t0) * 1000)
        db.setdefault("audit_log", [])
        db.setdefault("usage", {}).setdefault("requests", 0)
        db["usage"]["requests"] += 1
        rid = hashlib.sha1((endpoint + "|" + now + "|" + str(lat_ms) + "|" + str(db["usage"]["requests"])).encode("utf-8")).hexdigest()[:16]
        db["audit_log"].append({
            "id": rid,
            "timestamp": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": lat_ms
        })

    def _validate():
        if not isinstance(owner, str) or not owner.strip():
            return _err("VALIDATION_ERROR", "owner is required and must be a non-empty string")
        if not isinstance(repo, str) or not repo.strip():
            return _err("VALIDATION_ERROR", "repo is required and must be a non-empty string")
        if path is not None and not isinstance(path, str):
            return _err("VALIDATION_ERROR", "path must be a string")
        if ref is not None and not isinstance(ref, str):
            return _err("VALIDATION_ERROR", "ref must be a string")
        if sha is not None and not isinstance(sha, str):
            return _err("VALIDATION_ERROR", "sha must be a string")
        if ref and sha:
            return _err("CONFLICT", "ref and sha cannot both be provided")
        return None

    db = _ensure_store_shape(_load("github.json"))

    try:
        err = _validate()
        if err:
            status = "error"
            return err

        full = owner.strip() + "/" + repo.strip()
        req_path = (path if path is not None else "/")
        if req_path == "":
            req_path = "/"
        if not isinstance(req_path, str):
            status = "error"
            return _err("VALIDATION_ERROR", "path must be a string")

        # Ref/sha validity: must exist if provided (branch/tag/commit)
        if ref:
            branches = db.get("branches", []) or []
            tags = db.get("tags", []) or []
            pulls = db.get("pulls", []) or []
            ok = False
            if ref.startswith("refs/heads/"):
                bname = ref[len("refs/heads/"):]
                ok = any(b.get("repo") == full and b.get("name") == bname for b in branches)
            elif ref.startswith("refs/tags/"):
                tname = ref[len("refs/tags/"):]
                ok = any(t.get("repo") == full and t.get("name") == tname for t in tags)
            elif ref.startswith("refs/pull/") and ref.endswith("/head"):
                mid = ref[len("refs/pull/"):-len("/head")]
                try:
                    prn = int(mid)
                except Exception:
                    prn = None
                if prn is not None:
                    ok = any(p.get("repo") == full and int(p.get("number")) == prn for p in pulls)
            else:
                ok = False
            if not ok:
                status = "error"
                return _err("NOT_FOUND", "ref not found in repository", ref=ref)

        if sha:
            commits = db.get("commits", []) or []
            # accept any commit sha in repo; also accept file sha in repo files as a weak fallback
            ok = any(c.get("repo") == full and c.get("sha") == sha for c in commits)
            if not ok:
                files = db.get("files", []) or []
                ok = any(f.get("repo") == full and f.get("sha") == sha for f in files)
            if not ok:
                status = "error"
                return _err("NOT_FOUND", "sha not found in repository", sha=sha)

        files = [f for f in (db.get("files", []) or []) if f.get("repo") == full]

        # Directory listing
        if req_path == "/" or req_path.endswith("/"):
            prefix = "" if req_path == "/" else req_path.lstrip("/")
            items = []
            seen = set()
            for f in files:
                fp = f.get("path") or ""
                if not isinstance(fp, str):
                    continue
                if prefix and not fp.startswith(prefix):
                    continue
                rel = fp[len(prefix):] if prefix else fp
                rel = rel.lstrip("/")
                if rel == "":
                    continue
                name = rel.split("/", 1)[0]
                if name in seen:
                    continue
                seen.add(name)
                is_dir = "/" in rel
                if is_dir:
                    items.append({"name": name, "path": (prefix + ("" if prefix.endswith("/") or prefix == "" else "/") + name + "/") if prefix else (name + "/"),
                                  "type": "dir", "sha": None, "size": 0})
                else:
                    items.append({"name": name, "path": (prefix + ("" if prefix.endswith("/") or prefix == "" else "/") + name) if prefix else name,
                                  "type": f.get("type", "file"), "sha": f.get("sha"), "size": f.get("size", 0)})
            # Must refuse directories not expressed as trailing slash:
            # If caller gave non-slash path that is actually a directory prefix.
            return {"type": "dir", "path": req_path, "ref": ref, "sha": sha, "entries": items}

        # Non-directory path: refuse if it points to a directory prefix
        plain = req_path.lstrip("/")
        if any(((f.get("path") or "").startswith(plain + "/")) for f in files):
            status = "error"
            return _err("VALIDATION_ERROR", "directories must be requested with a trailing slash '/'", path=req_path)

        frow = next((f for f in files if (f.get("path") or "") == plain), None)
        if frow is None:
            status = "error"
            return _err("NOT_FOUND", "path not found in repository", path=req_path)

        txt = frow.get("content_text")
        if txt is None:
            txt = ""
        if not isinstance(txt, str):
            txt = str(txt)

        content_b64 = base64.b64encode(txt.encode("utf-8")).decode("ascii")
        resp = {
            "type": frow.get("type", "file"),
            "encoding": "base64",
            "name": os.path.basename(frow.get("path") or plain),
            "path": frow.get("path") or plain,
            "sha": frow.get("sha"),
            "size": frow.get("size", len(txt)),
            "content": content_b64,
            "html_url": frow.get("html_url"),
            "download_url": frow.get("download_url"),
            "ref": ref,
            "requested_sha": sha
        }
        return resp
    finally:
        # Always record traffic and persist
        try:
            _audit(db, "get_file_contents", status, (err.get("error", {}).get("code") if isinstance(err, dict) else None))
            _save("github.json", db)
        except Exception:
            # Must not raise; return is already decided.
            pass

