def issue_read(method, owner, repo, issue_number, page=None, perPage=None):
    import json, os
    db = json.load(open(os.path.join(_DB, "github.json"), encoding="utf-8"))
    full = owner + "/" + repo
    issues = [i for i in db.get("issues", []) if i.get("repo") == full]
    issue = next((i for i in issues if i.get("number") == issue_number),
                 (issues[0] if issues else (db.get("issues") or [{}])[0]))
    m = method or "get"
    if m == "get":
        return issue
    if m == "get_comments":
        num = issue.get("number")
        return [c for c in db.get("issue_comments", []) if c.get("repo") == full and c.get("issue_number") == num]
    if m == "get_labels":
        return issue.get("labels", [])
    if m == "get_sub_issues":
        return []
    return issue

def add_issue_comment(owner, repo, issue_number, body, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0110000" if __import__("os").path.isdir("./environment_mix/0110000") else "/app/database")
    def _load(n):
