    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "success"
    err = None

    def _ensure_store_shape(db):
        if isinstance(db, dict):
            return db
        return {"me": None, "users": [], "repos": [], "branches": [], "files": [], "issues": [], "issue_comments": [],
                "pulls": [], "pr_files": [], "commits": [], "tags": [], "releases": [], "labels": [], "teams": [],
                "issue_types": [], "reviews": [], "audit_log": [], "usage": {"requests": 0}}

    def _audit(db, endpoint, status, error_code=None):
        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        lat_ms = int((time.time() - t0) * 1000)
        db.setdefault("audit_log", [])
        db.setdefault("usage", {}).setdefault("requests", 0)
        db["usage"]["requests"] += 1
        rid = hashlib.sha1((endpoint + "|" + now + "|" + str(lat_ms) + "|" + str(db["usage"]["requests"])).encode("utf-8")).hexdigest()[:16]
        db["audit_log"].append({
            "id": rid,
            "timestamp": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": lat_ms
        })

    def _validate():
        if not isinstance(owner, str) or not owner.strip():
            return _err("VALIDATION_ERROR", "owner is required and must be a non-empty string")
        if not isinstance(repo, str) or not repo.strip():
            return _err("VALIDATION_ERROR", "repo is required and must be a non-empty string")
        # issue_number is number per schema; accept int-like floats
        if not isinstance(issue_number, (int, float)) or int(issue_number) != issue_number:
            return _err("VALIDATION_ERROR", "issue_number must be an integer")
        if not isinstance(body, str) or not body.strip():
            return _err("VALIDATION_ERROR", "body is required and must be a non-empty string")
        return None

    db = _ensure_store_shape(_load("github.json"))

    try:
        err = _validate()
        if err:
            status = "error"
            return err

        full = owner.strip() + "/" + repo.strip()
        ino = int(issue_number)
        issues = db.get("issues", []) or []
        pulls = db.get("pulls", []) or []
        exists = any(i.get("repo") == full and int(i.get("number")) == ino for i in issues)
        if not exists:
            # PRs are issues too
            exists = any(p.get("repo") == full and int(p.get("number")) == ino for p in pulls)
        if not exists:
            status = "error"
            return _err("NOT_FOUND", "issue or pull request not found", repo=full, issue_number=ino)

        me = db.get("me") or {"login": "octocat", "id": 1}
        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

        comments = db.setdefault("issue_comments", [])
        max_id = 0
        for c in comments:
            try:
                max_id = max(max_id, int(c.get("id") or 0))
            except Exception:
                continue
        cid = max_id + 1 if max_id else 1

        comment = {
            "repo": full,
            "issue_number": ino,
            "id": cid,
            "user": {"login": me.get("login"), "id": me.get("id")},
            "body": body,
            "created_at": now,
            "updated_at": now,
            "html_url": f"https://github.com/{full}/issues/{ino}#issuecomment-{cid}"
        }
        comments.append(comment)

        # update issue's updated_at if present
        touched = False
        for i in issues:
            if i.get("repo") == full and int(i.get("number")) == ino:
                i["updated_at"] = now
                touched = True
                break
        if not touched:
            for p in pulls:
                if p.get("repo") == full and int(p.get("number")) == ino:
                    p["updated_at"] = now
                    break

        _save("github.json", db)
        return comment
    finally:
        try:
            _audit(db, "add_issue_comment", status, (err.get("error", {}).get("code") if isinstance(err, dict) else None))
            _save("github.json", db)
        except Exception:
            pass

