_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0110000" if __import__("os").path.isdir("./environment_mix/0110000") else "/app/database")
def pull_request_read(method, owner, repo, pullNumber, page=None, perPage=None):
    import json, os
    db = json.load(open(os.path.join(_DB, "github.json"), encoding="utf-8"))
    full = owner + "/" + repo
    pulls = [p for p in db.get("pulls", []) if p.get("repo") == full]
    pr = next((p for p in pulls if p.get("number") == pullNumber), (pulls[0] if pulls else (db.get("pulls") or [{}])[0]))
    m = method or "get"
    if m == "get":
        return pr
    if m == "get_files":
        return [f for f in db.get("pr_files", []) if f.get("repo") == full and f.get("pull_number") == pr.get("number")]
    if m == "get_diff":
        files = [f for f in db.get("pr_files", []) if f.get("repo") == full and f.get("pull_number") == pr.get("number")]
        return {"diff": "\n".join(f.get("patch", "") for f in files)}
    if m == "get_status":
        return {"state": "success", "statuses": [{"context": "ci/lint", "state": "success"}],
                "sha": pr.get("head", {}).get("sha")}
    if m in ("get_reviews",):
        return [r for r in db.get("reviews", []) if r.get("repo") == full and r.get("pull_number") == pr.get("number")]
    if m in ("get_review_comments", "get_comments"):
        return []
    return pr

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0110000" if __import__("os").path.isdir("./environment_mix/0110000") else "/app/database")
def pull_request_review_write(method, owner, repo, pullNumber, body=None, commitID=None, event=None):
    import json, os, datetime
    db = json.load(open(os.path.join(_DB, "github.json"), encoding="utf-8"))
    full = owner + "/" + repo
    now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
    m = method or "create"
    state = "PENDING" if m == "create" else (event or "COMMENT")
    if m == "delete_pending":
        return {"repo": full, "pull_number": pullNumber, "status": "pending review deleted"}
    return {"id": 4100, "repo": full, "pull_number": pullNumber, "user": db["me"],
            "state": state, "body": body or "", "commit_id": commitID,
            "submitted_at": now if m == "submit_pending" else None}

def add_comment_to_pending_review(owner, repo, pullNumber, path, body, subjectType,
                                  line=None, side=None, startLine=None, startSide=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0110000" if __import__("os").path.isdir("./environment_mix/0110000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "success"
    err = None

    def _ensure_store_shape(db):
        if isinstance(db, dict):
            return db
        return {"me": None, "users": [], "repos": [], "branches": [], "files": [], "issues": [], "issue_comments": [],
                "pulls": [], "pr_files": [], "commits": [], "tags": [], "releases": [], "labels": [], "teams": [],
                "issue_types": [], "reviews": [], "audit_log": [], "usage": {"requests": 0}}

    def _audit(db, endpoint, status, error_code=None):
        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        lat_ms = int((time.time() - t0) * 1000)
        db.setdefault("audit_log", [])
        db.setdefault("usage", {}).setdefault("requests", 0)
        db["usage"]["requests"] += 1
        rid = hashlib.sha1((endpoint + "|" + now + "|" + str(lat_ms) + "|" + str(db["usage"]["requests"])).encode("utf-8")).hexdigest()[:16]
        db["audit_log"].append({
            "id": rid,
            "timestamp": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": lat_ms
        })

    def _validate():
        if not isinstance(owner, str) or not owner.strip():
            return _err("VALIDATION_ERROR", "owner is required and must be a non-empty string")
        if not isinstance(repo, str) or not repo.strip():
            return _err("VALIDATION_ERROR", "repo is required and must be a non-empty string")
        if not isinstance(pullNumber, (int, float)) or int(pullNumber) != pullNumber:
            return _err("VALIDATION_ERROR", "pullNumber must be an integer")
        if not isinstance(path, str) or not path.strip():
            return _err("VALIDATION_ERROR", "path is required and must be a non-empty string")
        if not isinstance(body, str) or not body.strip():
            return _err("VALIDATION_ERROR", "body is required and must be a non-empty string")
        if subjectType not in ("FILE", "LINE"):
            return _err("VALIDATION_ERROR", "subjectType must be FILE or LINE")
        if subjectType == "LINE":
            if line is None or not isinstance(line, (int, float)) or int(line) != line:
                return _err("VALIDATION_ERROR", "line is required for LINE comments and must be an integer")
            if side not in ("LEFT", "RIGHT"):
                return _err("VALIDATION_ERROR", "side is required for LINE comments and must be LEFT or RIGHT")
            if (startLine is None) != (startSide is None):
                return _err("VALIDATION_ERROR", "startLine and startSide must be provided together for multi-line comments")
            if startLine is not None:
                if not isinstance(startLine, (int, float)) or int(startLine) != startLine:
                    return _err("VALIDATION_ERROR", "startLine must be an integer")
                if startSide not in ("LEFT", "RIGHT"):
                    return _err("VALIDATION_ERROR", "startSide must be LEFT or RIGHT")
                if int(startLine) > int(line):
                    return _err("VALIDATION_ERROR", "startLine cannot be greater than line")
        return None

    db = _ensure_store_shape(_load("github.json"))
    try:
        err = _validate()
        if err:
            status = "error"
            return err

        full = owner.strip() + "/" + repo.strip()
        pn = int(pullNumber)
        pulls = db.get("pulls", []) or []
        pr = next((p for p in pulls if p.get("repo") == full and int(p.get("number")) == pn), None)
        if pr is None:
            status = "error"
            return _err("NOT_FOUND", "pull request not found", repo=full, pull_number=pn)

        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        me = db.get("me") or {"login": "octocat", "id": 1}
        # Persist as a review in COMMENTED state (best available collection in schema)
        reviews = db.setdefault("reviews", [])
        max_id = 0
        for r in reviews:
            try:
                max_id = max(max_id, int(r.get("id") or 0))
            except Exception:
                continue
        rid = max_id + 1 if max_id else 1

        loc = {
            "path": path,
            "subject_type": subjectType,
            "line": int(line) if line is not None else None,
            "side": side,
            "start_line": int(startLine) if startLine is not None else None,
            "start_side": startSide
        }
        review_row = {
            "repo": full,
            "pull_number": pn,
            "id": rid,
            "user": {"login": me.get("login"), "id": me.get("id")},
            "state": "COMMENTED",
            "body": body,
            "submitted_at": now,
            "location": loc
        }
        reviews.append(review_row)
        pr["updated_at"] = now

        _save("github.json", db)
        return {
            "repo": full,
            "pull_number": pn,
            "id": rid,
            "user": review_row["user"],
            "body": body,
            "path": path,
            "subjectType": subjectType,
            "line": int(line) if line is not None else None,
            "side": side or ("RIGHT" if subjectType == "LINE" else None),
            "startLine": int(startLine) if startLine is not None else None,
            "startSide": startSide,
            "created_at": now
        }
    finally:
        try:
            _audit(db, "add_comment_to_pending_review", status, (err.get("error", {}).get("code") if isinstance(err, dict) else None))
            _save("github.json", db)
        except Exception:
            pass

