def update_pull_request(owner, repo, pullNumber, base=None, body=None, draft=None,
                        maintainer_can_modify=None, reviewers=None, state=None, title=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0110000" if __import__("os").path.isdir("./environment_mix/0110000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "success"
    err = None

    def _ensure_store_shape(db):
        if isinstance(db, dict):
            return db
        return {"me": None, "users": [], "repos": [], "branches": [], "files": [], "issues": [], "issue_comments": [],
                "pulls": [], "pr_files": [], "commits": [], "tags": [], "releases": [], "labels": [], "teams": [],
                "issue_types": [], "reviews": [], "audit_log": [], "usage": {"requests": 0}}

    def _audit(db, endpoint, status, error_code=None):
        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        lat_ms = int((time.time() - t0) * 1000)
        db.setdefault("audit_log", [])
        db.setdefault("usage", {}).setdefault("requests", 0)
        db["usage"]["requests"] += 1
        rid = hashlib.sha1((endpoint + "|" + now + "|" + str(lat_ms) + "|" + str(db["usage"]["requests"])).encode("utf-8")).hexdigest()[:16]
        db["audit_log"].append({
            "id": rid,
            "timestamp": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": lat_ms
        })

    def _validate():
        if not isinstance(owner, str) or not owner.strip():
            return _err("VALIDATION_ERROR", "owner is required and must be a non-empty string")
        if not isinstance(repo, str) or not repo.strip():
            return _err("VALIDATION_ERROR", "repo is required and must be a non-empty string")
        if not isinstance(pullNumber, (int, float)) or int(pullNumber) != pullNumber:
            return _err("VALIDATION_ERROR", "pullNumber must be an integer")
        if base is not None and (not isinstance(base, str) or not base.strip()):
            return _err("VALIDATION_ERROR", "base must be a non-empty string")
        if body is not None and not isinstance(body, str):
            return _err("VALIDATION_ERROR", "body must be a string")
        if title is not None and (not isinstance(title, str) or not title.strip()):
            return _err("VALIDATION_ERROR", "title must be a non-empty string")
        if state is not None and state not in ("open", "closed"):
            return _err("VALIDATION_ERROR", "state must be open or closed")
        if draft is not None and not isinstance(draft, bool):
            return _err("VALIDATION_ERROR", "draft must be a boolean")
        if maintainer_can_modify is not None and not isinstance(maintainer_can_modify, bool):
            return _err("VALIDATION_ERROR", "maintainer_can_modify must be a boolean")
        if reviewers is not None:
            if not isinstance(reviewers, list) or any((not isinstance(x, str) or not x.strip()) for x in reviewers):
                return _err("VALIDATION_ERROR", "reviewers must be an array of non-empty strings")
        return None

    db = _ensure_store_shape(_load("github.json"))
    try:
        err = _validate()
        if err:
            status = "error"
            return err

        full = owner.strip() + "/" + repo.strip()
        pn = int(pullNumber)
        pulls = db.get("pulls", []) or []
        pr = next((p for p in pulls if p.get("repo") == full and int(p.get("number")) == pn), None)
        if pr is None:
            status = "error"
            return _err("NOT_FOUND", "pull request not found", repo=full, pull_number=pn)

        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

        if title is not None:
            pr["title"] = title
        if body is not None:
            pr["body"] = body
        if base is not None:
            pr.setdefault("base", {})
            # schema expects base.full_name; keep it consistent
            pr["base"]["full_name"] = full
            pr["base"]["ref"] = base
        if state is not None:
            pr["state"] = state
            if state == "closed":
                pr["closed_at"] = pr.get("closed_at") or now
            else:
                pr["closed_at"] = None
        if draft is not None:
            pr["draft"] = draft
        if maintainer_can_modify is not None:
            pr["maintainer_can_modify"] = maintainer_can_modify
        if reviewers is not None:
            pr["requested_reviewers"] = reviewers

        pr["updated_at"] = now
        _save("github.json", db)
        return pr
    finally:
        try:
            _audit(db, "update_pull_request", status, (err.get("error", {}).get("code") if isinstance(err, dict) else None))
            _save("github.json", db)
        except Exception:
            pass

def update_pull_request_branch(owner, repo, pullNumber, expectedHeadSha=None, **_extra):
