        db.setdefault("usage", {}).setdefault("requests", 0)
        db["usage"]["requests"] += 1
        rid = hashlib.sha1((endpoint + "|" + now + "|" + str(lat_ms) + "|" + str(db["usage"]["requests"])).encode("utf-8")).hexdigest()[:16]
        db["audit_log"].append({
            "id": rid,
            "timestamp": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": lat_ms
        })

    def _validate():
        if not isinstance(owner, str) or not owner.strip():
            return _err("VALIDATION_ERROR", "owner is required and must be a non-empty string")
        if not isinstance(repo, str) or not repo.strip():
            return _err("VALIDATION_ERROR", "repo is required and must be a non-empty string")
        if not isinstance(pullNumber, (int, float)) or int(pullNumber) != pullNumber:
            return _err("VALIDATION_ERROR", "pullNumber must be an integer")
        if expectedHeadSha is not None and (not isinstance(expectedHeadSha, str) or not expectedHeadSha.strip()):
            return _err("VALIDATION_ERROR", "expectedHeadSha must be a non-empty string")
        return None

    db = _ensure_store_shape(_load("github.json"))
    try:
        err = _validate()
        if err:
            status = "error"
            return err

        full = owner.strip() + "/" + repo.strip()
        pn = int(pullNumber)
        pulls = db.get("pulls", []) or []
        pr = next((p for p in pulls if p.get("repo") == full and int(p.get("number")) == pn), None)
        if pr is None:
            status = "error"
            return _err("NOT_FOUND", "pull request not found", repo=full, pull_number=pn)
        if pr.get("state") != "open":
            status = "error"
            return _err("INVALID_TRANSITION", "pull request branch can only be updated when pull request is open")

        head_sha = None
        head = pr.get("head") or {}
        if isinstance(head, dict):
            head_sha = head.get("sha")
        if expectedHeadSha is not None and head_sha is not None and expectedHeadSha != head_sha:
            status = "error"
            return _err("CONFLICT", "expectedHeadSha does not match current head sha", expectedHeadSha=expectedHeadSha, currentHeadSha=head_sha)

        # "Update branch" effect: change head sha and updated_at; add a commit row
        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        new_sha = hashlib.sha1((str(head_sha) + "|" + now + "|" + "".join(random.choice(string.ascii_letters) for _ in range(8))).encode("utf-8")).hexdigest()
        pr.setdefault("head", {})
        pr["head"]["sha"] = new_sha
        pr["updated_at"] = now

        commits = db.setdefault("commits", [])
        commits.append({
            "repo": full,
            "sha": new_sha,
            "commit": {"name": (db.get("me") or {}).get("name") or "The Octocat",
                       "email": (db.get("me") or {}).get("email") or "octocat@users.noreply.github.com",
                       "date": now},
            "author": {"login": (db.get("me") or {}).get("login") or "octocat", "id": (db.get("me") or {}).get("id") or 1},
            "committer": {"login": (db.get("me") or {}).get("login") or "octocat", "id": (db.get("me") or {}).get("id") or 1},
            "html_url": f"https://github.com/{full}/commit/{new_sha}",
            "stats": {"additions": 0, "deletions": 0, "total": 0},
            "files": []
        })

        _save("github.json", db)
        return {
            "repo": full,
            "pull_number": pn,
            "message": "Pull request branch updated.",
            "head_sha": new_sha,
            "updated_at": now,
            "url": f"https://api.github.com/repos/{full}/pulls/{pn}/update-branch"
        }
    finally:
        try:
            _audit(db, "update_pull_request_branch", status, (err.get("error", {}).get("code") if isinstance(err, dict) else None))
            _save("github.json", db)
        except Exception:
            pass

