    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "success"
    err = None

    def _ensure_store_shape(db):
        if isinstance(db, dict):
            return db
        return {"me": None, "users": [], "repos": [], "branches": [], "files": [], "issues": [], "issue_comments": [],
                "pulls": [], "pr_files": [], "commits": [], "tags": [], "releases": [], "labels": [], "teams": [],
                "issue_types": [], "reviews": [], "audit_log": [], "usage": {"requests": 0}}

    def _audit(db, endpoint, status, error_code=None):
        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        lat_ms = int((time.time() - t0) * 1000)
        db.setdefault("audit_log", [])
        db.setdefault("usage", {}).setdefault("requests", 0)
        db["usage"]["requests"] += 1
        rid = hashlib.sha1((endpoint + "|" + now + "|" + str(lat_ms) + "|" + str(db["usage"]["requests"])).encode("utf-8")).hexdigest()[:16]
        db["audit_log"].append({
            "id": rid,
            "timestamp": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": lat_ms
        })

    def _validate():
        if not isinstance(owner, str) or not owner.strip():
            return _err("VALIDATION_ERROR", "owner is required and must be a non-empty string")
        if not isinstance(repo, str) or not repo.strip():
            return _err("VALIDATION_ERROR", "repo is required and must be a non-empty string")
        if not isinstance(title, str) or not title.strip():
            return _err("VALIDATION_ERROR", "title is required and must be a non-empty string")
        if not isinstance(head, str) or not head.strip():
            return _err("VALIDATION_ERROR", "head is required and must be a non-empty string")
        if not isinstance(base, str) or not base.strip():
            return _err("VALIDATION_ERROR", "base is required and must be a non-empty string")
        if body is not None and not isinstance(body, str):
            return _err("VALIDATION_ERROR", "body must be a string")
        if draft is not None and not isinstance(draft, bool):
            return _err("VALIDATION_ERROR", "draft must be a boolean")
        if maintainer_can_modify is not None and not isinstance(maintainer_can_modify, bool):
            return _err("VALIDATION_ERROR", "maintainer_can_modify must be a boolean")
        return None

    db = _ensure_store_shape(_load("github.json"))
    try:
        err = _validate()
        if err:
            status = "error"
            return err

        full = owner.strip() + "/" + repo.strip()

        # Validate branches exist
        branches = db.get("branches", []) or []
        if not any(b.get("repo") == full and b.get("name") == head for b in branches):
            status = "error"
            return _err("NOT_FOUND", "head branch not found", head=head)
        if not any(b.get("repo") == full and b.get("name") == base for b in branches):
            status = "error"
            return _err("NOT_FOUND", "base branch not found", base=base)

        pulls = db.setdefault("pulls", [])
        # Prevent duplicate open PR from same head->base (simplified)
        if any(p.get("repo") == full and p.get("state") == "open"
               and (p.get("head") or {}).get("ref") == head and (p.get("base") or {}).get("ref") == base for p in pulls):
            status = "error"
            return _err("CONFLICT", "a pull request already exists for this head and base", head=head, base=base)

        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        max_num = 0
        max_id = 0
        for p in pulls:
            try: max_num = max(max_num, int(p.get("number") or 0))
            except Exception: pass
            try: max_id = max(max_id, int(p.get("id") or 0))
            except Exception: pass
        num = max_num + 1 if max_num else 1
        pid = max_id + 1 if max_id else 1

        def _branch_sha(bname):
            b = next((x for x in branches if x.get("repo") == full and x.get("name") == bname), None)
            if b and isinstance(b.get("commit"), dict):
                return b["commit"].get("sha")
            return None

        head_sha = _branch_sha(head) or hashlib.sha1((full + "|head|" + head + "|" + now).encode("utf-8")).hexdigest()
        base_sha = _branch_sha(base) or hashlib.sha1((full + "|base|" + base + "|" + now).encode("utf-8")).hexdigest()
        me = db.get("me") or {"login": "octocat", "id": 1}

        pr = {
            "repo": full,
            "number": num,
            "id": pid,
            "node_id": "PR_" + "".join(random.choice(string.ascii_letters + string.digits) for _ in range(8)),
            "title": title,
            "state": "open",
            "draft": bool(draft) if draft is not None else False,
            "merged": False,
            "body": body or "",
            "user": {"login": me.get("login"), "id": me.get("id")},
            "head": {"full_name": full, "ref": head, "sha": head_sha},
            "base": {"full_name": full, "ref": base, "sha": base_sha},
            "mergeable": True,
            "merged_at": None,
            "created_at": now,
            "updated_at": now,
            "closed_at": None,
            "html_url": f"https://github.com/{full}/pull/{num}"
        }
        if maintainer_can_modify is not None:
            pr["maintainer_can_modify"] = maintainer_can_modify

        pulls.append(pr)
        _save("github.json", db)
        return pr
    finally:
        try:
            _audit(db, "create_pull_request", status, (err.get("error", {}).get("code") if isinstance(err, dict) else None))
            _save("github.json", db)
        except Exception:
            pass

