        })

    def _validate():
        if not isinstance(name, str) or not name.strip():
            return _err("VALIDATION_ERROR", "name is required and must be a non-empty string")
        # Simple GitHub-ish name rule
        nm = name.strip()
        if any(ch.isspace() for ch in nm) or "/" in nm:
            return _err("VALIDATION_ERROR", "invalid repository name", name=name)
        if autoInit is not None and not isinstance(autoInit, bool):
            return _err("VALIDATION_ERROR", "autoInit must be a boolean")
        if description is not None and not isinstance(description, str):
