def create_branch(owner, repo, branch, from_branch=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0110000" if __import__("os").path.isdir("./environment_mix/0110000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "success"
    err = None

    def _ensure_store_shape(db):
        if isinstance(db, dict):
            return db
        return {"me": None, "users": [], "repos": [], "branches": [], "files": [], "issues": [], "issue_comments": [],
                "pulls": [], "pr_files": [], "commits": [], "tags": [], "releases": [], "labels": [], "teams": [],
                "issue_types": [], "reviews": [], "audit_log": [], "usage": {"requests": 0}}

    def _audit(db, endpoint, status, error_code=None):
        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        lat_ms = int((time.time() - t0) * 1000)
        db.setdefault("audit_log", [])
        db.setdefault("usage", {}).setdefault("requests", 0)
        db["usage"]["requests"] += 1
        rid = hashlib.sha1((endpoint + "|" + now + "|" + str(lat_ms) + "|" + str(db["usage"]["requests"])).encode("utf-8")).hexdigest()[:16]
        db["audit_log"].append({
            "id": rid,
            "timestamp": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": lat_ms
        })

    def _validate():
        if not isinstance(owner, str) or not owner.strip():
            return _err("VALIDATION_ERROR", "owner is required and must be a non-empty string")
        if not isinstance(repo, str) or not repo.strip():
            return _err("VALIDATION_ERROR", "repo is required and must be a non-empty string")
        if not isinstance(branch, str) or not branch.strip():
            return _err("VALIDATION_ERROR", "branch is required and must be a non-empty string")
        if from_branch is not None and (not isinstance(from_branch, str) or not from_branch.strip()):
            return _err("VALIDATION_ERROR", "from_branch must be a non-empty string")
        if "/" in branch.strip() and branch.strip().startswith("refs/"):
            return _err("VALIDATION_ERROR", "branch must be a branch name, not a full ref")
        return None

    db = _ensure_store_shape(_load("github.json"))
    try:
        err = _validate()
        if err:
            status = "error"
            return err

        full = owner.strip() + "/" + repo.strip()
        repos = db.get("repos", []) or []
        if repos and not any(r.get("full_name") == full for r in repos):
            status = "error"
            return _err("NOT_FOUND", "repository not found", repo=full)

        branches = db.setdefault("branches", [])
        new_name = branch.strip()
        if any(b.get("repo") == full and b.get("name") == new_name for b in branches):
            status = "error"
            return _err("CONFLICT", "branch already exists", branch=new_name)

        src = from_branch.strip() if from_branch else None
        if src is None:
            r = next((r for r in repos if r.get("full_name") == full), None)
            src = (r.get("default_branch") if isinstance(r, dict) else None) or "main"

        src_row = next((b for b in branches if b.get("repo") == full and b.get("name") == src), None)
        if src_row is None:
            status = "error"
            return _err("NOT_FOUND", "source branch not found", from_branch=src)

        src_sha = (src_row.get("commit") or {}).get("sha") or hashlib.sha1((full + "|branch|" + src).encode("utf-8")).hexdigest()
        branch_row = {
            "repo": full,
            "name": new_name,
            "protected": False,
            "commit": {"sha": src_sha, "url": f"https://api.github.com/repos/{full}/git/commits/{src_sha}"}
        }
        branches.append(branch_row)
        _save("github.json", db)

        return {
            "ref": "refs/heads/" + new_name,
            "object": {"sha": src_sha, "type": "commit", "url": branch_row["commit"]["url"]},
            "repo": full
        }
    finally:
        try:
            _audit(db, "create_branch", status, (err.get("error", {}).get("code") if isinstance(err, dict) else None))
            _save("github.json", db)
        except Exception:
            pass

def create_or_update_file(owner, repo, path, content, message, branch, sha=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0110000" if __import__("os").path.isdir("./environment_mix/0110000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "success"
    err = None

    def _ensure_store_shape(db):
        if isinstance(db, dict):
            return db
        return {"me": None, "users": [], "repos": [], "branches": [], "files": [], "issues": [], "issue_comments": [],
                "pulls": [], "pr_files": [], "commits": [], "tags": [], "releases": [], "labels": [], "teams": [],
                "issue_types": [], "reviews": [], "audit_log": [], "usage": {"requests": 0}}

    def _audit(db, endpoint, status, error_code=None):
        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        lat_ms = int((time.time() - t0) * 1000)
        db.setdefault("audit_log", [])
        db.setdefault("usage", {}).setdefault("requests", 0)
        db["usage"]["requests"] += 1
        rid = hashlib.sha1((endpoint + "|" + now + "|" + str(lat_ms) + "|" + str(db["usage"]["requests"])).encode("utf-8")).hexdigest()[:16]
        db["audit_log"].append({
            "id": rid,
            "timestamp": now,
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": lat_ms
        })

    def _validate():
        if not isinstance(owner, str) or not owner.strip():
            return _err("VALIDATION_ERROR", "owner is required and must be a non-empty string")
        if not isinstance(repo, str) or not repo.strip():
            return _err("VALIDATION_ERROR", "repo is required and must be a non-empty string")
        if not isinstance(path, str) or not path.strip():
            return _err("VALIDATION_ERROR", "path is required and must be a non-empty string")
        if path.strip().endswith("/"):
            return _err("VALIDATION_ERROR", "path must point to a file, not a directory")
        if not isinstance(content, str):
            return _err("VALIDATION_ERROR", "content must be a string")
        if not isinstance(message, str) or not message.strip():
            return _err("VALIDATION_ERROR", "message is required and must be a non-empty string")
        if not isinstance(branch, str) or not branch.strip():
            return _err("VALIDATION_ERROR", "branch is required and must be a non-empty string")
        if sha is not None and (not isinstance(sha, str) or not sha.strip()):
            return _err("VALIDATION_ERROR", "sha must be a non-empty string when provided")
        return None

    db = _ensure_store_shape(_load("github.json"))
    try:
        err = _validate()
        if err:
            status = "error"
            return err

        full = owner.strip() + "/" + repo.strip()
        bname = branch.strip()
        pth = path.strip().lstrip("/")

        branches = db.get("branches", []) or []
        if not any(b.get("repo") == full and b.get("name") == bname for b in branches):
            status = "error"
            return _err("NOT_FOUND", "branch not found", branch=bname)

        files = db.setdefault("files", [])
        existing = next((f for f in files if f.get("repo") == full and (f.get("path") or "") == pth and (f.get("ref") or "") == bname), None)

        if existing is not None:
            # update requires sha match
            if sha is None:
                status = "error"
                return _err("VALIDATION_ERROR", "sha is required when updating an existing file")
            if existing.get("sha") != sha:
                status = "error"
                return _err("CONFLICT", "sha does not match current file sha", provided_sha=sha, current_sha=existing.get("sha"))
            is_create = False
        else:
            # create: sha must be absent
            if sha is not None:
                status = "error"
                return _err("VALIDATION_ERROR", "sha must not be provided when creating a new file")
            is_create = True

        now = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
        blob_sha = hashlib.sha1(content.encode("utf-8")).hexdigest()
        commit_sha = hashlib.sha1((message + "|" + full + "|" + bname + "|" + pth + "|" + now).encode("utf-8")).hexdigest()

        if is_create:
            row = {
                "repo": full,
                "path": pth,
                "ref": bname,
                "type": "file",
                "sha": blob_sha,
                "size": len(content.encode("utf-8")),
                "encoding": "utf-8",
                "content_text": content,
                "html_url": f"https://github.com/{full}/blob/{bname}/{pth}",
                "download_url": f"https://raw.githubusercontent.com/{full}/{bname}/{pth}"
            }
            files.append(row)
        else:
            existing["sha"] = blob_sha
            existing["size"] = len(content.encode("utf-8"))
            existing["encoding"] = "utf-8"
            existing["content_text"] = content
            existing["html_url"] = f"https://github.com/{full}/blob/{bname}/{pth}"
            existing["download_url"] = f"https://raw.githubusercontent.com/{full}/{bname}/{pth}"

        # record commit and bump branch head sha
        commits = db.setdefault("commits", [])
        me = db.get("me") or {"login": "octocat", "id": 1, "name": "The Octocat", "email": "octocat@users.noreply.github.com"}
        commits.append({
            "repo": full,
            "sha": commit_sha,
            "commit": {"name": me.get("name") or "The Octocat", "email": me.get("email") or "octocat@users.noreply.github.com", "date": now},
            "author": {"login": me.get("login") or "octocat", "id": me.get("id") or 1},
            "committer": {"login": me.get("login") or "octocat", "id": me.get("id") or 1},
            "html_url": f"https://github.com/{full}/commit/{commit_sha}",
            "stats": {"additions": 0, "deletions": 0, "total": 0},
            "files": [{"filename": pth, "status": "added" if is_create else "modified", "additions": 0, "deletions": 0, "changes": 0}]
        })
        for b in branches:
            if b.get("repo") == full and b.get("name") == bname:
                b.setdefault("commit", {})
                b["commit"]["sha"] = commit_sha
                b["commit"]["url"] = f"https://api.github.com/repos/{full}/git/commits/{commit_sha}"
                break

        # update repo updated_at if present
        repos = db.get("repos", []) or []
        r = next((r for r in repos if r.get("full_name") == full), None)
        if isinstance(r, dict):
            r["updated_at"] = now

        _save("github.json", db)
        return {
            "content": {
                "name": os.path.basename(pth),
                "path": pth,
                "sha": blob_sha,
                "size": len(content.encode("utf-8")),
                "type": "file",
                "html_url": f"https://github.com/{full}/blob/{bname}/{pth}"
            },
            "commit": {
                "sha": commit_sha,
                "message": message,
                "html_url": f"https://github.com/{full}/commit/{commit_sha}",
                "author": {"date": now},
                "committer": {"date": now}
            }
        }
    finally:
        try:
            _audit(db, "create_or_update_file", status, (err.get("error", {}).get("code") if isinstance(err, dict) else None))
            _save("github.json", db)
        except Exception:
            pass

